1	/*
2	 * hub: the single writer (DESIGN.md Section 2). Accepts sensor daemons on
3	 * $PSS_RUN_DIR/hub.sock, turns PIR edges into events, asks camd for an image
4	 * burst per event, and commits everything through the store (mechanism D).
5	 *
6	 * Fusion (DESIGN.md Section 4, src/analysis/fusion.c): a PIR rise opens a
7	 * MOTION_ONLY event and a sound onset (below) opens a SOUND_ONLY event, but
8	 * neither takes images. Only when a rise and an onset fall within +-T_co of
9	 * each other (either order) does the event become an ENTRY: it is made
10	 * durable at once and camd is asked for a burst, once per event.
11	 *
12	 * M3 sound trigger (stand-in for DESIGN.md Section 4's detectors, M4): an
13	 * EWMA background model of spectral flux and log RMS, learned only while no
14	 * event is open. A frame is an onset when its flux z-score and its loudness
15	 * above the room background both pass thresholds, so steady noise (fans,
16	 * AC) never triggers: its flux stays near its own mean and its level is the
17	 * background. Thresholds are placeholders until tuned on Pi recordings.
18	 *
19	 * Exit codes: 0 on SIGTERM/SIGINT, 1 on error (including any store write
20	 * failure, so the supervisor restarts us and recovery runs), 2 on usage.
21	 */
22	#include "analysis/fusion.h"
23	#include "common/ipc.h"
24	#include "common/log.h"
25	#include "common/time.h"
26	#include "common/util.h"
27	#include "store/clip.h"
28	#include "store/evlog.h"
29	
30	#include <errno.h>
31	#include <getopt.h>
32	#include <inttypes.h>
33	#include <math.h>
34	#include <signal.h>
