527	static int write_boot(struct hub *h)
528	{
529		struct pss_rec_boot b;
530	
531		memset(&b, 0, sizeof b);
532		b.boot_no = h->store.boot_no + 1;
533		b.mono_ns = pss_mono_ns();
534		b.wall_ns = pss_wall_ns();
535		if (store_append(&h->store, PSS_LOG_EVENTS, PSS_REC_BOOT, &b, sizeof b) != 0 ||
536		    store_sync(&h->store, PSS_LOG_EVENTS) != 0)
537			return -1;
538		h->store.boot_no = b.boot_no;
539		pss_log("boot #%" PRIu64 " recorded; next event id %" PRIu64, b.boot_no, h->store.next_event_id);
540		return 0;
541	}
