601	int main(int argc, char **argv)
602	{
603		const int sigs[] = { SIGINT, SIGTERM };
604		struct hub *h = &hub;
605		int code = 1;
606	
607		pss_log_init("hub");
608		h->listen_fd = h->epoll_fd = h->sig_fd = h->tick_fd = -1;
609		for (int i = 0; i < MAX_CONNS; i++)
610			h->conns[i].fd = -1;
611		if (parse_args(h, argc, argv) != 0) {
612			usage();
613			return EXIT_USAGE;
614		}
615	
616		h->sig_fd = pss_signalfd(sigs, 2);
617		if (h->sig_fd < 0)
618			goto out;
619		if (mkdir(pss_run_dir(), 0755) != 0 && errno != EEXIST) {
620			pss_log("mkdir %s: %s", pss_run_dir(), strerror(errno));
621			goto out;
622		}
623		if (store_open(&h->store, pss_data_dir()) != 0)
624			goto out;
625		h->store_open = 1;
626		if (write_boot(h) != 0)
627			goto out;
628		if (ipc_sock_path(h->sock_path, sizeof h->sock_path) != 0)
629			goto out;
630		h->listen_fd = ipc_listen(h->sock_path);
631		if (h->listen_fd < 0)
632			goto out;
633		h->tick_fd = pss_timerfd(PSS_NS_PER_S, PSS_NS_PER_S);
634		if (h->tick_fd < 0)
635			goto out;
636		h->epoll_fd = epoll_create1(EPOLL_CLOEXEC);
637		if (h->epoll_fd < 0) {
638			pss_log("epoll_create1: %s", strerror(errno));
639			goto out;
640		}
641		if (epoll_add(h, h->listen_fd, TAG_LISTEN) != 0 || epoll_add(h, h->sig_fd, TAG_SIG) != 0 ||
642		    epoll_add(h, h->tick_fd, TAG_TICK) != 0)
643			goto out;
644	
645		h->start_ns = pss_mono_ns();
646		h->next_hb_ns = h->start_ns + HB_FIRST_NS;
647		pss_log("start pid=%d data=%s sock=%s quiet=%" PRId64 "ms burst=%" PRIu32 "x%" PRIu32 "ms onset z>=%.0f +%.0fdB warmup=%" PRIu32 " t_co=%" PRId64 "ms",
648			(int)getpid(), pss_data_dir(), h->sock_path, h->quiet_ns / PSS_NS_PER_MS,
649			h->burst_frames, h->burst_interval_ms, h->onset_z, h->onset_db, h->mic_warmup,
650			h->t_co_ns / PSS_NS_PER_MS);
651	
652		for (;;) {
653			struct epoll_event evs[16];
654			int n = epoll_wait(h->epoll_fd, evs, 16, -1);
655			int64_t now;
656	
657			if (n < 0) {
658				if (errno == EINTR)
659					continue;
660				pss_log("epoll_wait: %s", strerror(errno));
661				goto out;
662			}
663			now = pss_mono_ns();
664			for (int i = 0; i < n; i++) {
665				uint32_t tag = evs[i].data.u32;
666	
667				if (tag == TAG_SIG) {
668					struct signalfd_siginfo si;
669	
670					if (read(h->sig_fd, &si, sizeof si) != (ssize_t)sizeof si)
671						pss_log("signalfd read: %s", strerror(errno));
672					else
673						pss_log("signal %u, shutting down", si.ssi_signo);
674					if (h->ev.open) {
675						if (h->ev.burst == BURST_PENDING)
676							h->ev.flags |= PSS_EVF_NO_IMAGES;
677						if (close_event(h, now, PSS_EVF_CLOSED_AT_SHUTDOWN) != 0)
678							goto out;
679					}
680					code = 0;
681					goto out;
682				} else if (tag == TAG_LISTEN) {
683					accept_all(h, now);
684				} else if (tag == TAG_TICK) {
685					if (pss_timerfd_drain(h->tick_fd) != 0 || tick(h, now) != 0)
686						goto out;
687				} else if (tag < MAX_CONNS) {
688					conn_readable(h, (int)tag, now);
689				}
690				if (h->fatal)
691					goto out;
692			}
693		}
694	out:
695		for (int i = 0; i < MAX_CONNS; i++)
696			if (h->conns[i].fd >= 0)
697				close(h->conns[i].fd);
698		if (h->epoll_fd >= 0)
699			close(h->epoll_fd);
700		if (h->listen_fd >= 0) {
701			close(h->listen_fd);
702			if (unlink(h->sock_path) != 0)
703				pss_log("unlink %s: %s", h->sock_path, strerror(errno));
704		}
705		if (h->tick_fd >= 0)
706			close(h->tick_fd);
707		if (h->sig_fd >= 0)
708			close(h->sig_fd);
709		if (h->store_open)
710			store_close(&h->store);
711		pss_log("exit %d", code);
712		return code;
713	}
