509	int store_open(struct pss_store *s, const char *root)
510	{
511		struct open_scan scan = { .s = s };
512		struct store_recovery *rec = &s->recovered;
513		uint64_t max_clip = 0;
514		int ret = -1;
515	
516		memset(s, 0, sizeof *s);
517		s->root_fd = s->clips_dir_fd = -1;
518		s->events.dir_fd = s->events.seg_fd = -1;
519		s->stats.dir_fd = s->stats.seg_fd = -1;
520		s->stats_roll_ns = PSS_STATS_ROLL_NS;
521		s->next_event_id = 1;
522	
523		if (mkdir(root, 0755) != 0 && errno != EEXIST) {
524			pss_log("store: mkdir %s: %s", root, strerror(errno));
525			goto out;
526		}
527		s->root_fd = open(root, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
528		if (s->root_fd < 0) {
529			pss_log("store: open %s: %s", root, strerror(errno));
530			goto out;
531		}
532	
533		if (seglog_open(&s->events, s->root_fd, "events", open_visitor, &scan,
534				&rec->valid_records, &rec->truncated_bytes) != 0)
535			goto out;
536		rec->seg_no = s->events.seg_no;
537	
538		if (seglog_open(&s->stats, s->root_fd, "stats", NULL, NULL,
539				&rec->stats_valid_records, &rec->stats_truncated_bytes) != 0)
540			goto out;
541		rec->stats_seg_no = s->stats.seg_no;
542		/* A fresh stats segment per boot (and per day, see store_append) keeps
543		 * segments short enough to be deleted whole after 7 days. */
544		if (s->stats.seg_size > 0 && rollover(&s->stats) != 0)
545			goto out;
546		if (stats_prune(s, &rec->stats_pruned) != 0)
547			goto out;
548	
549		s->clips_dir_fd = open_dir_at(s->root_fd, "clips", 1);
550		if (s->clips_dir_fd < 0)
551			goto out;
552		if (clip_cleanup_tmp(s->clips_dir_fd, &rec->tmp_removed) != 0)
553			goto out;
554		if (clip_max_id(s->clips_dir_fd, &max_clip) != 0)
555			goto out;
556		bump_next_id(s, max_clip);
557	
558		if (close_interrupted(s, &scan) != 0)
559			goto out;
560		ret = 0;
561	out:
562		free(scan.opens);
563		if (ret != 0)
564			store_close(s);
565		return ret;
566	}
