43		(void)seg;
44		(void)ver;
45		if (type == PSS_REC_EVENT && len == sizeof s->last) {
46			memcpy(&s->last, p, sizeof s->last);
47			s->events++;
48		} else if (type == PSS_REC_EVENT_OPEN && len == sizeof s->last_open) {
49			memcpy(&s->last_open, p, sizeof s->last_open);
50			s->opens++;
51		} else if (type == PSS_REC_BOOT && len == sizeof(struct pss_rec_boot)) {
52			struct pss_rec_boot b;
53	
54			memcpy(&b, p, sizeof b);
55			if (b.boot_no > s->max_boot)
56				s->max_boot = b.boot_no;
57			s->boots++;
58		}
59		return 0;
60	}
61	
62	static void sleep_ms(long ms)
63	{
64		struct timespec ts = { ms / 1000, (ms % 1000) * 1000000L };
65	
66		while (nanosleep(&ts, &ts) != 0 && errno == EINTR)
67			;
68	}
69	
70	static pid_t spawn(char *const argv[])
71	{
72		pid_t pid = fork();
73	
74		if (pid == 0) {
75			execv(argv[0], argv);
76			perror(argv[0]);
77			_exit(127);
78		}
79		return pid;
80	}
81	
82	/* SIGTERM, then wait up to 5 s; returns the exit status or -1. */
83	static int stop(pid_t pid)
84	{
85		int st;
86	
87		if (pid <= 0)
88			return -1;
89		kill(pid, SIGTERM);
90		for (int i = 0; i < 500; i++) {
91			pid_t r = waitpid(pid, &st, WNOHANG);
92	
93			if (r == pid)
94				return WIFEXITED(st) ? WEXITSTATUS(st) : -1;
95			sleep_ms(10);
96		}
97		kill(pid, SIGKILL);
98		waitpid(pid, &st, 0);
99		return -1;
100	}
101	
102	static int connect_retry(const char *path)
103	{
104		for (int i = 0; i < 500; i++) {
105			int fd = ipc_connect(path);
106	
107			if (fd >= 0)
108				return fd;
109			sleep_ms(10);
110		}
111		return -1;
112	}
113	
114	static void send_edge(int fd, int rising)
115	{
116		struct pss_msg m;
117	
118		pss_msg_init(&m, PSS_MSG_PIR_EDGE);
119		m.u.pir.rising = (uint32_t)rising;
120		CHECK(ipc_send(fd, &m) == 0);
121	}
122	
123	/* One hub+camd lifetime with one PIR-triggered event. Fills *out from disk. */
124	static void run_session(const char *data, struct seen *out)
125	{
126		char hub[512], camd[512], sock[300];
127		const char *bindir = getenv("PSS_BIN_DIR");
128		struct pss_msg m;
129		struct seen before = { 0 };
130		pid_t hp, cp;
131		int fd;
132	
133		snprintf(hub, sizeof hub, "%s/hub", bindir);
134		snprintf(camd, sizeof camd, "%s/camd", bindir);
135		if (access(data, F_OK) == 0)
136			CHECK(store_scan(data, PSS_LOG_EVENTS, seen_visitor, &before) == 0);
137	
138		hp = spawn((char *[]){ hub, "--quiet-ms=300", "--burst-frames=3", "--burst-interval-ms=20", NULL });
139		CHECK(hp > 0);
140		CHECK(ipc_sock_path(sock, sizeof sock) == 0);
141		fd = connect_retry(sock);
142		CHECK(fd >= 0);
143		cp = spawn((char *[]){ camd, NULL });
144		CHECK(cp > 0);
145	
146		/* Act as pird. */
147		pss_msg_init(&m, PSS_MSG_HELLO);
148		m.u.hello.role = PSS_ROLE_PIR;
149		m.u.hello.pid = (uint32_t)getpid();
150		CHECK(ipc_send(fd, &m) == 0);
151		sleep_ms(1000); /* let camd connect */
152		send_edge(fd, 1);
153		sleep_ms(50);
154		send_edge(fd, 0);
155	
156		/* Event closes after the burst returns and 300 ms of quiet (1 s tick). */
157		for (int i = 0; i < 100; i++) {
158			memset(out, 0, sizeof *out);
159			CHECK(store_scan(data, PSS_LOG_EVENTS, seen_visitor, out) == 0);
160			if (out->events > before.events)
161				break;
162			sleep_ms(100);
163		}
164		CHECK(out->events == before.events + 1);
165		CHECK(stop(cp) == 0);
166		CHECK(stop(hp) == 0);
167		close(fd);
168	}
169	
170	static int count_entries(const char *dir, const char *suffix)
171	{
172		DIR *d = opendir(dir);
173		struct dirent *e;
174		int n = 0;
175	
176		if (d == NULL)
177			return -1;
178		while ((e = readdir(d)) != NULL) {
179			size_t len = strlen(e->d_name), m = strlen(suffix);
180	
181			if (len >= m && strcmp(e->d_name + len - m, suffix) == 0)
182				n++;
183		}
184		closedir(d);
185		return n;
186	}
187	
188	static void test_pir_to_storage(void)
189	{
190		char root[256], data[300], run[300], fake[512], path[600];
191		struct seen s = { 0 };
192		uint64_t first_id;
193	
194		t_mkdtemp(root);
195		snprintf(data, sizeof data, "%s/data", root);
196		snprintf(run, sizeof run, "%s/run", root);
197		snprintf(fake, sizeof fake, "%s/fake-rpicam-still.sh", getenv("PSS_TEST_DIR"));
198		CHECK(chmod(fake, 0755) == 0);
199		setenv("PSS_DATA_DIR", data, 1);
200		setenv("PSS_RUN_DIR", run, 1);
201		setenv("PSS_RPICAM", fake, 1);
202	
203		/* Session 1: motion alone is logged as MOTION_ONLY and takes no images
204		 * (the camera is for confirmed entries only; see test_entry_to_storage). */
205		unsetenv("FAKE_RPICAM_FAIL");
206		run_session(data, &s);
207		first_id = s.last.event_id;
208		CHECK(s.boots == 1 && s.max_boot == 1);
209		CHECK(s.last.kind == PSS_EV_MOTION_ONLY);
210		CHECK(s.last.n_images == 0);
211		CHECK(!(s.last.flags & PSS_EVF_NO_IMAGES));	/* no burst was asked for, none failed */
212		CHECK(s.last.flags & PSS_EVF_AUDIO_OFFLINE); /* no micd running */
213		CHECK(s.last.pir_edges == 1);
214		CHECK(s.last.end_mono_ns >= s.last.start_mono_ns);
215		CHECK(s.opens == 0);
216		snprintf(path, sizeof path, "%s/clips/%" PRIu64 ".dir", data, first_id);
217		CHECK(count_entries(path, ".jpg") == -1);	/* no clip directory at all */
218		snprintf(path, sizeof path, "%s/stats", data);
219		CHECK(count_entries(path, ".pel") >= 1);	/* stats log lives apart from events */
220		snprintf(path, sizeof path, "%s/events", data);
221		CHECK(count_entries(path, ".pel") == 1);
222	
223		/* Session 2: same data dir. Ids continue, boot count grows. (The camera
224		 * failure case moved to test_entry_to_storage: only an ENTRY bursts.) */
225		run_session(data, &s);
226		CHECK(s.boots == 2 && s.max_boot == 2);
227		CHECK(s.last.event_id == first_id + 1);
228		CHECK(s.last.kind == PSS_EV_MOTION_ONLY);
229		CHECK(s.last.n_images == 0);
230	
231		snprintf(path, sizeof path, "%s/clips", data);
232		CHECK(count_entries(path, ".tmp") == 0);
233		unsetenv("FAKE_RPICAM_FAIL");
234		t_rm_rf(root);
235	}
236	
237	/* Uniform in [-1, 1), deterministic so the test is repeatable. */
238	static double lcg_unit(uint32_t *st)
239	{
240		*st = *st * 1664525u + 1013904223u;
241		return (double)(*st >> 8) / (double)(1u << 23) - 1.0;
242	}
243	
244	static void send_mic_frame(int fd, double rms, double flux)
245	{
246		struct pss_msg m;
247	
248		pss_msg_init(&m, PSS_MSG_MIC_FRAME);
249		m.u.mic.rms = (float)rms;
250		m.u.mic.flux = (float)flux;
251		for (int b = 0; b < PSS_NBANDS; b++)
252			m.u.mic.band[b] = (float)log10(rms * rms);
253		for (int i = 0; i < 500; i++) {
254			if (ipc_send(fd, &m) == 0)
255				return;
256			if (errno != EAGAIN)
257				break;
258			sleep_ms(1);	/* socket buffer full: let the hub drain it */
259		}
260		CHECK(!"send_mic_frame failed");
261	}
262	
263	/* Fan-like noise: level rms_lvl with +-10% jitter, flux 0.3 +- 0.1. */
264	static void send_fan(int fd, uint32_t *st, double rms_lvl)
265	{
266		send_mic_frame(fd, rms_lvl * (1.0 + 0.1 * lcg_unit(st)), 0.3 + 0.1 * lcg_unit(st));
267	}
268	
269	static int count_events(const char *data, struct seen *out)
270	{
271		memset(out, 0, sizeof *out);
272		CHECK(store_scan(data, PSS_LOG_EVENTS, seen_visitor, out) == 0);
273		return out->events;
274	}
