1	/* Fusion: PIR rise + sound onset within +-T_co confirms an entry. */
2	#include "t.h"
3	
4	#include "analysis/fusion.h"
5	
6	#define MS 1000000LL
7	#define S 1000000000LL
8	
9	static void test_rise_then_onset(void)
10	{
11		struct fusion f;
12		int64_t dt = 0;
13	
14		fusion_init(&f, 3 * S);
15		CHECK(fusion_rise(&f, 100 * S, &dt) == 0);		/* nothing heard yet */
16		CHECK(fusion_onset(&f, 100 * S + 2900 * MS, &dt) == 1);
17		CHECK(dt == 2900 * MS);
18	
19		fusion_init(&f, 3 * S);
20		CHECK(fusion_rise(&f, 100 * S, NULL) == 0);
21		CHECK(fusion_onset(&f, 100 * S + 3100 * MS, NULL) == 0);	/* too late */
22	}
23	
24	static void test_onset_then_rise(void)
25	{
26		struct fusion f;
27		int64_t dt = 0;
28	
29		/* The usual door: latch sound first, then the person walks into view. */
30		fusion_init(&f, 3 * S);
31		CHECK(fusion_onset(&f, 50 * S, &dt) == 0);
32		CHECK(fusion_rise(&f, 51 * S, &dt) == 1);
33		CHECK(dt == -1 * S);
34	
35		fusion_init(&f, 3 * S);
36		CHECK(fusion_onset(&f, 50 * S, NULL) == 0);
37		CHECK(fusion_rise(&f, 54 * S, NULL) == 0);	/* sound was 4 s before */
38	}
39	
40	static void test_boundary_inclusive(void)
41	{
