62		fusion_init(&f, 3 * S);
63		CHECK(fusion_rise(&f, 20 * S, NULL) == 0);
64		CHECK(fusion_onset(&f, 19 * S, &dt) == 1);
65		CHECK(dt == -1 * S);
66	}
67	
