{
	if (c->fd < 0) {
		c->dropped++;
		return -1;
	}
	m->seq = c->seq++;
	if (ipc_send(c->fd, m) == 0)
		return 0;
	c->dropped++;
	if (errno != EAGAIN)
		client_disconnect(c, pss_mono_ns(), strerror(errno));
	return -1;
}

void client_disconnect(struct pss_client *c, int64_t now_ns, const char *why)
{
	if (c->fd < 0)
