	fclose(f);
}

/* Starts the supervisor with stderr appended to e->log. */
static pid_t start_sup(const struct env *e, char *const extra[])
{
	char cfg[400];
	char *argv[16];
	int n = 0;
	pid_t pid;

	snprintf(cfg, sizeof cfg, "--config=%s", e->conf);
	argv[n++] = (char *)e->sup;
	argv[n++] = cfg;
	for (int i = 0; extra[i] != NULL && n < 15; i++)
		argv[n++] = extra[i];
