}

static int read_kids(const struct env *e, struct kid k[MAXK])
{
	FILE *f = fopen(e->pids, "r");
	int n = 0;

	if (f == NULL)
		return 0;
	while (n < MAXK && fscanf(f, "%d %31s", &k[n].pid, k[n].name) == 2)
		n++;
	fclose(f);
	return n;
}

