{
	struct kid k[MAXK];
	int n = read_kids(e, k);

	for (int i = 0; i < n; i++)
		if (strcmp(k[i].name, name) == 0)
			return k[i].pid;
	return 0;
}

/* Waits (up to 5 s) until `name` runs with a pid other than `not`. */
static int wait_pid(const struct env *e, const char *name, int not)
{
	for (int i = 0; i < 500; i++) {
		int p = pid_of(e, name);

		if (p > 0 && p != not)
			return p;
		sleep_ms(10);
