	CHECK(log_has(&e, "hanger heartbeat missed") >= 1);
	CHECK(log_has(&e, "hanger killed by signal 9 (hung), restart #1") == 1);
	CHECK(log_has(&e, "silent no heartbeat") >= 1);
	CHECK(log_has(&e, "silent killed by signal 9 (hung), restart #1") == 1);
